"""Control de Desperdicio de Papel - Metrocolor
Dale DOBLE CLIC a este archivo. La primera vez crea la carpeta
Documentos/Control_Desperdicio_Papel_Metrocolor con todo lo necesario y abre la app.
Las siguientes veces solo abre la app (tus datos se conservan).
Requisito: Python 3 instalado (python.org, marcar "Add Python to PATH").
"""
import base64, io, os, sys, zipfile
from pathlib import Path

VERSION = "2026.11.01-2"
NOMBRE = "Control_Desperdicio_Papel_Metrocolor"


def carpeta_destino() -> Path:
    for base in (Path.home() / "Documents", Path.home() / "Documentos", Path.home()):
        if base.is_dir():
            return base / NOMBRE
    return Path(__file__).resolve().parent / NOMBRE


def instalar(destino: Path) -> None:
    marca = destino / "version.txt"
    if marca.exists() and marca.read_text().strip() == VERSION:
        return
    print("Preparando la carpeta:", destino)
    destino.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(DATOS))) as z:
        for info in z.infolist():
            if info.filename.startswith("datos/papel.db"):
                continue  # nunca se sobrescribe la base de datos
            ruta = destino / info.filename
            if info.is_dir():
                ruta.mkdir(parents=True, exist_ok=True)
                continue
            ruta.parent.mkdir(parents=True, exist_ok=True)
            ruta.write_bytes(z.read(info))
    marca.write_text(VERSION)
    print("Carpeta lista.")


def main() -> None:
    destino = carpeta_destino()
    instalar(destino)
    os.chdir(destino)
    sys.path.insert(0, str(destino))
    import servidor
    sys.argv = [str(destino / "servidor.py")] + sys.argv[1:]
    servidor.main()


